/**
 * Major commercial ports. Location, cargo profile and activity come from IMF
 * PortWatch (AIS-derived; IMF / University of Oxford), generated by
 * scripts/build-ports.mjs → src/data/ports-portwatch.json:
 *  - coordinates and UN/LOCODE from the PortWatch ports database,
 *  - top industries (by trade value) from the same database,
 *  - port calls and estimated trade volume summed over one calendar year.
 *
 * Hand-entered below: which ports are shown, display names, and the `type`
 * label (our own classification for the map legend, not a PortWatch field).
 * No container-throughput (TEU) figures are shown: there is no free source we
 * can cite per port. See DATA_PROVENANCE.md.
 */
import portwatch from '../data/ports-portwatch.json'

export type PortType = 'container' | 'bulk' | 'oil' | 'lng' | 'naval' | 'fishing' | 'mixed'

export interface PortActivity {
  year: number
  portCalls: number
  containerCalls: number
  tankerCalls: number
  /** Estimated imports + exports, million metric tonnes */
  tradeMt: number
}

export interface Port {
  id: string
  name: string
  country: string
  lat: number
  lng: number
  type: PortType
  /** Top industries by trade value, PortWatch */
  topIndustry: string
  portwatchName: string
  locode: string | null
  activity: PortActivity | null
  notes?: string
}


export const PORT_TYPE_COLORS: Record<PortType, string> = {
  container: '#00ccff',
  bulk:      '#ffaa00',
  oil:       '#ff4400',
  lng:       '#44ff88',
  naval:     '#ff2266',
  fishing:   '#88aaff',
  mixed:     '#cccccc',
}

export const PORT_TYPE_LABELS: Record<PortType, string> = {
  container: 'Container',
  bulk:      'Bulk Cargo',
  oil:       'Oil Terminal',
  lng:       'LNG Terminal',
  naval:     'Naval Port',
  fishing:   'Fishing Port',
  mixed:     'Mixed',
}

type Placement = Pick<Port, 'id' | 'name' | 'country' | 'type' | 'notes'>
type PortWatchRow = (typeof portwatch.ports)[keyof typeof portwatch.ports]

