const rows = portwatch.ports as Record<string, PortWatchRow>

export const PORTS: Port[] = PLACEMENTS.filter(p => rows[p.id]).map(p => {
  const r = rows[p.id]
  return {
    ...p,
    lat: r.lat,
    lng: r.lng,
    topIndustry: r.topIndustries.join(', '),
    portwatchName: r.portwatchName,
    locode: r.locode,
    activity: r.activity ? {
      year: portwatch.year,
      portCalls: r.activity.portCalls,
      containerCalls: r.activity.containerCalls,
      tankerCalls: r.activity.tankerCalls,
      tradeMt: r.activity.tradeMt,
    } : null,
  }
})
